function drawTrend(){if(!trend)return;const c=trend.getContext('2d');c.clearRect(0,0,trend.width,trend.height);c.strokeStyle='#285263';c.beginPath();c.moveTo(0,130);c.lineTo(640,130);c.stroke();if(history.length<2)return;const max=Math.max(1,...history.map(v=>v.population));for(const [key,color,scale] of [['population','#5be4d0',max],['oxygen','#e9bd79',14]]){c.strokeStyle=color;c.lineWidth=2;c.beginPath();history.forEach((v,i)=>{const x=i/(history.length-1)*630+5,y=128-Math.max(0,Math.min(1,v[key]/scale))*112;i?c.lineTo(x,y):c.moveTo(x,y)});c.stroke()}}
