function pick(px,py){const pt=worldAt(px,py);let best=null,dist=Infinity;for(const o of organisms()){const dd=(o.x-pt.x)**2+(o.y-pt.y)**2;if(dd<dist){dist=dd;best=o}}if(best&&dist<Math.pow(26/(Math.min(width/WORLD.w,height/WORLD.h)*camera.zoom),2)){selected=best.id;inspect();draw()}}
function pointerDown(e){cameraVelocity={x:0,y:0};canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});gesture.moved=false;if(pointers.size===1){gesture.start={x:e.clientX,y:e.clientY};gesture.camera={x:camera.x,y:camera.y}}else if(pointers.size===2){const pts=[...pointers.values()],mid={x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2};gesture.distance=Math.max(1,Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y));gesture.zoom=camera.zoom;gesture.camera={x:camera.x,y:camera.y};gesture.mid=mid;gesture.anchor=worldAt(mid.x-canvas.getBoundingClientRect().left,mid.y-canvas.getBoundingClientRect().top)}}
function pointerMove(e){if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1){const dx=e.clientX-gesture.start.x,dy=e.clientY-gesture.start.y;if(Math.abs(dx)+Math.abs(dy)>7)gesture.moved=true;if(gesture.moved){camera.x=gesture.camera.x-dx*WORLD.w/(width*camera.zoom);camera.y=gesture.camera.y-dy*WORLD.h/(height*camera.zoom);cameraVelocity={x:0,y:0};lastPointerMove=performance.now();clampCamera();tank.classList.add('dragging');draw()}}else if(pointers.size===2){const pts=[...pointers.values()],dist=Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y),mid={x:(pts[0].x+pts[1].x)/2,y:(pts[0].y+pts[1].y)/2},rect=canvas.getBoundingClientRect();camera.zoom=Math.max(.25,Math.min(80,gesture.zoom*Math.pow(dist/gesture.distance,.72)));const px=mid.x-rect.left,py=mid.y-rect.top;camera.x=gesture.anchor.x-(px-width/2)*WORLD.w/(width*camera.zoom);camera.y=gesture.anchor.y-(py-height/2)*WORLD.h/(height*camera.zoom);clampCamera();$('zoom-value').textContent='ZOOM '+camera.zoom.toFixed(1)+'×';gesture.moved=true;draw()}}
