const configFields={'cfg-width':['world_width',Number],'cfg-height':['world_height',Number],'cfg-rain':['rain_rate',Number],'cfg-speed':['simulation_speed',Number],'cfg-motion':['movement_scale',Number],'cfg-current':['current_strength',Number],'cfg-capacity':['max_organisms',Number],'cfg-water':['initial_water_fraction',v=>Number(v)/100],'cfg-checkpoint':['checkpoint_interval',Number],'cfg-fixed':['fixed_dt',Number],'cfg-frame':['max_frame_dt',Number],'cfg-fluid':['initial_fluid_particles',Number],'cfg-predation':['predation_intensity',Number]};
